  <script>
    (function () {
      const DURATION_SEC = 35;
      const DURATION_MS = DURATION_SEC * 1000;
      const startTime = performance.now();

      const marks = [];
      const labelsHistory = [];
      const elementsHistory = [
        { name: 'buyer', visibleFrom: 0, visibleTo: null },
        { name: 'agent', visibleFrom: 0, visibleTo: null },
        { name: 'spend', visibleFrom: 0, visibleTo: null },
        { name: 'vault', visibleFrom: 0, visibleTo: null },
        { name: 'merchant', visibleFrom: 0, visibleTo: null },
        { name: 'chain', visibleFrom: 0, visibleTo: null }
      ];

      function nowMs() {
        return Math.max(0, Math.round(performance.now() - startTime));
      }

      function addLabel(text, t, orderId) {
        if (!text) return;
        const last = labelsHistory[labelsHistory.length - 1];
        if (last && last.text === text && last.orderId === orderId) return;
        const entry = { text: String(text), t: typeof t === 'number' ? Math.round(t) : nowMs() };
        if (orderId) entry.orderId = String(orderId);
        labelsHistory.push(entry);
      }

      function addElement(name, t, orderId) {
        const existing = elementsHistory.find(e => e.name === name && e.visibleTo === null);
        if (existing) return existing;
        const entry = {
          name: String(name),
          visibleFrom: typeof t === 'number' ? Math.round(t) : nowMs(),
          visibleTo: null
        };
        if (orderId) entry.orderId = String(orderId);
        elementsHistory.push(entry);
        return entry;
      }

      function removeElement(name, t) {
        const entry = elementsHistory.find(e => e.name === name && e.visibleTo === null);
        if (entry) {
          entry.visibleTo = typeof t === 'number' ? Math.round(t) : nowMs();
        }
      }

      function addMark(kind, orderId, element, t) {
        if (marks.some(m => m.orderId === orderId && m.kind === kind)) return;
        marks.push({
          t: typeof t === 'number' ? Math.round(t) : nowMs(),
          kind: String(kind),
          orderId: String(orderId),
          element: String(element)
        });
      }

      addLabel('Buyer', 0);
      addLabel('Gemini Agent', 0);
      addLabel('Spend Policy', 0);
      addLabel('Basis Theory Vault', 0);
      addLabel('Merchant', 0);
      addLabel('Base Sepolia', 0);

      window.__theater = {
        duration: DURATION_SEC,
        marks: marks,
        done: false,
        snapshot: function () {
          return {
            labels: labelsHistory.map(function (l) {
              const out = { text: l.text, t: l.t };
              if (l.orderId) out.orderId = l.orderId;
              return out;
            }),
            elements: elementsHistory.map(function (e) {
              const out = {
                name: e.name,
                visibleFrom: e.visibleFrom,
                visibleTo: e.visibleTo !== null ? e.visibleTo : DURATION_MS
              };
              if (e.orderId) out.orderId = e.orderId;
              return out;
            })
          };
        }
      };

      window.__theaterInternal = {
        startTime: startTime,
        DURATION_SEC: DURATION_SEC,
        DURATION_MS: DURATION_MS,
        nowMs: nowMs,
        addLabel: addLabel,
        addElement: addElement,
        removeElement: removeElement,
        addMark: addMark
      };
    })();
  </script>
