  <script type="module">
    import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.170.0/build/three.module.js';

    const internal = window.__theaterInternal;
    const rawEvents = JSON.parse(document.getElementById('events').textContent);

    const refusedEvent = rawEvents.find(e => e.kind === 'refused') || rawEvents[0];
    const settledEvent = rawEvents.find(e => e.kind === 'settled') || rawEvents[1];

    const ORD_REFUSED = refusedEvent.orderId;
    const CODE_REFUSED = refusedEvent.code;
    const ORD_SETTLED = settledEvent.orderId;
    const AMT_SETTLED = `${settledEvent.amount} USDC`;
    const HASH_SETTLED = settledEvent.txHash.slice(0, 10);

    // Timeline schedule in milliseconds (Total duration: 35,000ms)
    const T_BEAT1_START = 2000;     // Packet 1 starts: agent -> spend -> vault
    const T_BEAT1_SPEND = 4200;     // Packet 1 reaches spend policy
    const T_BEAT1_REFUSED = 6500;   // Packet 1 reaches vault -> Vault refuses payment
    const T_BEAT1_CLEAR = 14400;    // Clear temporary packet/refusal before Beat 2

    const T_BEAT2_START = 15000;    // Packet 2 starts: agent -> spend -> vault
    const T_BEAT2_SPEND = 16900;    // Packet 2 reaches spend policy
    const T_BEAT2_VAULT = 18600;    // Packet 2 reaches vault -> Vault seals in blue
    const T_BEAT2_COIN = 20200;     // Red coin starts: buyer -> merchant
    const T_BEAT2_MERCHANT = 24600; // Red coin lands at merchant -> Merchant lights up
    const T_BEAT2_LEDGER = 25200;   // Appended red block on Base Sepolia chain + receipt
    const T_DONE = 34000;           // After >4.5s final hold, mark done = true

    const container = document.getElementById('stage-container');
    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0xf3ead7);

    const camera = new THREE.PerspectiveCamera(37, window.innerWidth / window.innerHeight, 0.1, 100);
    camera.position.set(0, 6.3, 19.2);
    camera.lookAt(0, 0.45, 0);
    camera.updateMatrixWorld();

    const renderer = new THREE.WebGLRenderer({ antialias: true, powerPreference: 'high-performance' });
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.setPixelRatio(1);
    container.insertBefore(renderer.domElement, container.firstChild);

    // Lighting
    const ambientLight = new THREE.AmbientLight(0xfff8eb, 1.45);
    scene.add(ambientLight);

    const dirLight = new THREE.DirectionalLight(0xfffdf7, 1.45);
