    const matPaperDark = new THREE.MeshStandardMaterial({ color: 0xc2b08e, roughness: 0.85 });
    const matInk = new THREE.MeshStandardMaterial({ color: 0x26221e, roughness: 0.65 });
    const matYellow = new THREE.MeshStandardMaterial({ color: 0xeab308, emissive: 0x854d0e, emissiveIntensity: 0.25, roughness: 0.35 });
    const matBlueVault = new THREE.MeshStandardMaterial({ color: 0x1d4ed8, roughness: 0.35, metalness: 0.15 });
