    const matBlueSeal = new THREE.MeshStandardMaterial({ color: 0x2563eb, emissive: 0x1d4ed8, emissiveIntensity: 0.45, roughness: 0.25 });
    const matRedChain = new THREE.MeshStandardMaterial({ color: 0xdc2626, roughness: 0.35, metalness: 0.1 });
    const matRedDark = new THREE.MeshStandardMaterial({ color: 0x991b1b, roughness: 0.45 });

    // Ground platform & stage rail
    const stageBase = new THREE.Mesh(
      new THREE.BoxGeometry(21.4, 0.36, 5.8),
      new THREE.MeshStandardMaterial({ color: 0xe6d8bc, roughness: 0.9 })
    );
    stageBase.position.set(0, -0.18, 0);
    scene.add(stageBase);

    const stageBorder = new THREE.Mesh(
      new THREE.BoxGeometry(21.6, 0.1, 6.0),
      matInk
    );
    stageBorder.position.set(0, -0.32, 0);
    scene.add(stageBorder);

    // Station X positions (left to right)
    const X_POS = {
      buyer: -8.5,
      agent: -5.1,
      spend: -1.7,
      vault: 1.7,
