      const beacon = new THREE.Mesh(new THREE.SphereGeometry(0.13, 20, 20), matYellow);
      beacon.position.set(0, 2.2, 0);
      agentGroup.add(beacon);

      const accentRing = new THREE.Mesh(new THREE.TorusGeometry(0.65, 0.035, 12, 36), matYellow);
