      accentRing.position.set(0, 0.88, 0);
      agentGroup.add(accentRing);
    }

    // 3. SPEND POLICY (x = -1.7): gate or checkpoint
    const spendGroup = createPedestal(X_POS.spend);
    let spendGateArm;
    {
      const leftPillar = new THREE.Mesh(new THREE.BoxGeometry(0.32, 1.85, 0.36), matPaperMid);
      leftPillar.position.set(-0.62, 1.08, 0);
      spendGroup.add(leftPillar);

      const rightPillar = new THREE.Mesh(new THREE.BoxGeometry(0.32, 1.85, 0.36), matPaperMid);
      rightPillar.position.set(0.62, 1.08, 0);
      spendGroup.add(rightPillar);

      const headerArch = new THREE.Mesh(new THREE.BoxGeometry(1.68, 0.34, 0.44), matInk);
      headerArch.position.set(0, 2.08, 0);
      spendGroup.add(headerArch);

      spendGateArm = new THREE.Group();
      spendGateArm.position.set(-0.48, 1.15, 0.18);
      const armBar = new THREE.Mesh(new THREE.BoxGeometry(1.02, 0.12, 0.08), matPaperLight);
      armBar.position.set(0.46, 0, 0);
      spendGateArm.add(armBar);

      const stripe1 = new THREE.Mesh(new THREE.BoxGeometry(0.18, 0.125, 0.085), matInk);
      stripe1.position.set(0.25, 0, 0);
      spendGateArm.add(stripe1);

      const stripe2 = new THREE.Mesh(new THREE.BoxGeometry(0.18, 0.125, 0.085), matInk);
      stripe2.position.set(0.68, 0, 0);
      spendGateArm.add(stripe2);

      spendGroup.add(spendGateArm);
    }

    // 4. BASIS THEORY VAULT (x = +1.7): blue vault box; the key is drawn inside it and never leaves it
    const vaultGroup = createPedestal(X_POS.vault, 0xc7d7f4);
    let vaultKeyMat;
    let vaultSealRing;
    {
      const backWall = new THREE.Mesh(new THREE.BoxGeometry(1.62, 1.62, 0.16), matBlueVault);
      backWall.position.set(0, 0.98, -0.52);
      vaultGroup.add(backWall);

      const floorWall = new THREE.Mesh(new THREE.BoxGeometry(1.62, 0.16, 1.2), matBlueVault);
      floorWall.position.set(0, 0.24, 0);
      vaultGroup.add(floorWall);

      const roofWall = new THREE.Mesh(new THREE.BoxGeometry(1.62, 0.18, 1.2), matBlueVault);
      roofWall.position.set(0, 1.72, 0);
      vaultGroup.add(roofWall);

      const leftWall = new THREE.Mesh(new THREE.BoxGeometry(0.18, 1.62, 1.2), matBlueVault);
      leftWall.position.set(-0.72, 0.98, 0);
      vaultGroup.add(leftWall);

      const rightWall = new THREE.Mesh(new THREE.BoxGeometry(0.18, 1.62, 1.2), matBlueVault);
      rightWall.position.set(0.72, 0.98, 0);
      vaultGroup.add(rightWall);

      const frontGlass = new THREE.Mesh(
        new THREE.BoxGeometry(1.28, 1.32, 0.04),
        new THREE.MeshStandardMaterial({
          color: 0x93c5fd,
          transparent: true,
          opacity: 0.22,
          roughness: 0.1
        })
      );
      frontGlass.position.set(0, 0.98, 0.56);
      vaultGroup.add(frontGlass);

      // THE KEY INSIDE THE VAULT (Static — never moves, never leaves the vault)
      const keyGroup = new THREE.Group();
      keyGroup.position.set(0, 0.98, 0.05);

      vaultKeyMat = new THREE.MeshStandardMaterial({
        color: 0xfef08a,
        emissive: 0x60a5fa,
        emissiveIntensity: 0.35,
        roughness: 0.25,
        metalness: 0.3
      });

      const keyBow = new THREE.Mesh(new THREE.TorusGeometry(0.22, 0.06, 16, 32), vaultKeyMat);
      keyBow.position.set(-0.28, 0, 0);
