      const keyShaft = new THREE.Mesh(new THREE.CylinderGeometry(0.048, 0.048, 0.62, 16), vaultKeyMat);
      keyShaft.rotation.z = Math.PI / 2;
      keyShaft.position.set(0.18, 0, 0);
      keyGroup.add(keyShaft);

      const tooth1 = new THREE.Mesh(new THREE.BoxGeometry(0.08, 0.18, 0.06), vaultKeyMat);
      tooth1.position.set(0.28, -0.11, 0);
      keyGroup.add(tooth1);

      const tooth2 = new THREE.Mesh(new THREE.BoxGeometry(0.08, 0.13, 0.06), vaultKeyMat);
      tooth2.position.set(0.41, -0.085, 0);
      keyGroup.add(tooth2);

      vaultGroup.add(keyGroup);

      vaultSealRing = new THREE.Mesh(
        new THREE.TorusGeometry(0.95, 0.055, 16, 48),
