      vaultSealRing.rotation.x = Math.PI / 2;
      vaultSealRing.position.set(0, 1.88, 0);
      vaultSealRing.visible = false;
      vaultGroup.add(vaultSealRing);
    }

    // 5. MERCHANT (x = +5.1): storefront; dark until it is paid
    const merchantGroup = createPedestal(X_POS.merchant);
    let merchantBodyMat;
    let merchantWindowMat;
    let merchantSignMat;
    let merchantGlowLight;
    {
      merchantBodyMat = new THREE.MeshStandardMaterial({ color: 0x231f1d, roughness: 0.85 });
      merchantWindowMat = new THREE.MeshStandardMaterial({
        color: 0x181513,
        emissive: 0x000000,
        emissiveIntensity: 0,
        roughness: 0.4
      });
      merchantSignMat = new THREE.MeshStandardMaterial({
        color: 0x332d29,
        emissive: 0x000000,
        emissiveIntensity: 0,
        roughness: 0.5
      });

      const storeBody = new THREE.Mesh(new THREE.BoxGeometry(1.58, 1.38, 1.15), merchantBodyMat);
      storeBody.position.set(0, 0.85, 0);
      merchantGroup.add(storeBody);

      const awning = new THREE.Mesh(new THREE.BoxGeometry(1.68, 0.22, 0.42), merchantSignMat);
      awning.position.set(0, 1.36, 0.62);
      awning.rotation.x = 0.25;
      merchantGroup.add(awning);

      const leftWin = new THREE.Mesh(new THREE.BoxGeometry(0.52, 0.58, 0.06), merchantWindowMat);
      leftWin.position.set(-0.36, 0.78, 0.57);
      merchantGroup.add(leftWin);

      const rightWin = new THREE.Mesh(new THREE.BoxGeometry(0.52, 0.58, 0.06), merchantWindowMat);
      rightWin.position.set(0.36, 0.78, 0.57);
