      merchantGlowLight = new THREE.PointLight(0xfef08a, 0, 5);
      merchantGlowLight.position.set(0, 1.2, 1.1);
      merchantGroup.add(merchantGlowLight);
    }

    function setMerchantLit(isLit) {
      if (isLit) {
        merchantBodyMat.color.setHex(0xede0c8);
        merchantWindowMat.color.setHex(0xfef08a);
        merchantWindowMat.emissive.setHex(0xfacc15);
        merchantWindowMat.emissiveIntensity = 0.85;
        merchantSignMat.color.setHex(0xd97706);
        merchantSignMat.emissive.setHex(0xf59e0b);
        merchantSignMat.emissiveIntensity = 0.45;
        merchantGlowLight.intensity = 2.2;
      } else {
        merchantBodyMat.color.setHex(0x231f1d);
        merchantWindowMat.color.setHex(0x181513);
        merchantWindowMat.emissive.setHex(0x000000);
        merchantWindowMat.emissiveIntensity = 0;
        merchantSignMat.color.setHex(0x332d29);
        merchantSignMat.emissive.setHex(0x000000);
        merchantSignMat.emissiveIntensity = 0;
        merchantGlowLight.intensity = 0;
      }
    }

    // 6. BASE SEPOLIA CHAIN (x = +8.5): row of red linked blocks
    const chainGroup = createPedestal(X_POS.chain, 0xf2d3cf);
    let appendedLedgerBlockGroup = null;
    let ledgerPulseRing = null;
    {
      const rail = new THREE.Mesh(new THREE.BoxGeometry(2.1, 0.1, 0.55), matInk);
      rail.position.set(0, 0.21, 0);
      chainGroup.add(rail);

      const blockXPositions = [-0.72, -0.24, 0.24];
      for (let i = 0; i < blockXPositions.length; i++) {
        const bx = blockXPositions[i];
        const blk = new THREE.Mesh(new THREE.BoxGeometry(0.34, 0.34, 0.34), matRedChain);
        blk.position.set(bx, 0.52, 0);
        chainGroup.add(blk);

        const wireframe = new THREE.LineSegments(
          new THREE.EdgesGeometry(new THREE.BoxGeometry(0.35, 0.35, 0.35)),
          new THREE.LineBasicMaterial({ color: 0x450a0a })
        );
        wireframe.position.copy(blk.position);
        chainGroup.add(wireframe);

        if (i > 0) {
          const link = new THREE.Mesh(new THREE.CylinderGeometry(0.045, 0.045, 0.2, 12), matRedDark);
          link.rotation.z = Math.PI / 2;
          link.position.set(bx - 0.24, 0.52, 0);
          chainGroup.add(link);
        }
      }

      appendedLedgerBlockGroup = new THREE.Group();
      appendedLedgerBlockGroup.position.set(0.72, 0.52, 0);
      appendedLedgerBlockGroup.visible = false;

      const newLink = new THREE.Mesh(new THREE.CylinderGeometry(0.05, 0.05, 0.2, 12), matRedDark);
      newLink.rotation.z = Math.PI / 2;
      newLink.position.set(-0.24, 0, 0);
      appendedLedgerBlockGroup.add(newLink);

      const newBlkMat = new THREE.MeshStandardMaterial({
        color: 0xef4444,
        emissive: 0xdc2626,
        emissiveIntensity: 0.55,
        roughness: 0.25
      });
      const newBlk = new THREE.Mesh(new THREE.BoxGeometry(0.38, 0.38, 0.38), newBlkMat);
      appendedLedgerBlockGroup.add(newBlk);

      const newEdges = new THREE.LineSegments(
        new THREE.EdgesGeometry(new THREE.BoxGeometry(0.39, 0.39, 0.39)),
        new THREE.LineBasicMaterial({ color: 0x7f1d1d })
      );
      appendedLedgerBlockGroup.add(newEdges);

      ledgerPulseRing = new THREE.Mesh(
        new THREE.RingGeometry(0.28, 0.38, 32),
        new THREE.MeshBasicMaterial({
          color: 0xdc2626,
          side: THREE.DoubleSide,
          transparent: true,
          opacity: 0.9
        })
      );
      ledgerPulseRing.position.set(0, 0, 0.24);
      appendedLedgerBlockGroup.add(ledgerPulseRing);

      chainGroup.add(appendedLedgerBlockGroup);
    }

    // Dynamic 3D objects: Yellow Packet, Blue Refusal Seal with Cross, Red Coin
    const packetGroup = new THREE.Group();
    packetGroup.visible = false;
    {
      const envBody = new THREE.Mesh(new THREE.BoxGeometry(0.56, 0.38, 0.14), matYellow);
      packetGroup.add(envBody);

      const envFlap = new THREE.Mesh(
        new THREE.ConeGeometry(0.34, 0.22, 4),
        new THREE.MeshStandardMaterial({ color: 0xca8a04, roughness: 0.4 })
      );
      envFlap.rotation.z = Math.PI;
      envFlap.rotation.y = Math.PI / 4;
      envFlap.position.set(0, 0.08, 0.05);
      packetGroup.add(envFlap);

      const packetBlueSeal = new THREE.Mesh(
        new THREE.CylinderGeometry(0.14, 0.14, 0.18, 24),
        matBlueSeal
      );
      packetBlueSeal.rotation.x = Math.PI / 2;
      packetBlueSeal.position.set(0, 0, 0.04);
      packetBlueSeal.name = 'packetBlueSeal';
      packetBlueSeal.visible = false;
      packetGroup.add(packetBlueSeal);
    }
    scene.add(packetGroup);

    // Refusal mark at Vault: Blue seal with a cross
    const refusalGroup = new THREE.Group();
    refusalGroup.position.set(X_POS.vault, 2.25, 0.45);
    refusalGroup.visible = false;
    {
      const sealDisc = new THREE.Mesh(
        new THREE.CylinderGeometry(0.46, 0.46, 0.12, 32),
        matBlueSeal
      );
      sealDisc.rotation.x = Math.PI / 2;
      refusalGroup.add(sealDisc);

      const sealRim = new THREE.Mesh(
        new THREE.TorusGeometry(0.46, 0.045, 16, 36),
        matBlueTrim
      );
      refusalGroup.add(sealRim);

      const crossMat = new THREE.MeshStandardMaterial({
        color: 0xffffff,
        emissive: 0xeff6ff,
        emissiveIntensity: 0.5,
        roughness: 0.2
      });
      const bar1 = new THREE.Mesh(new THREE.BoxGeometry(0.56, 0.11, 0.16), crossMat);
      bar1.rotation.z = Math.PI / 4;
      bar1.position.z = 0.04;
      refusalGroup.add(bar1);

      const bar2 = new THREE.Mesh(new THREE.BoxGeometry(0.56, 0.11, 0.16), crossMat);
      bar2.rotation.z = -Math.PI / 4;
      bar2.position.z = 0.04;
      refusalGroup.add(bar2);
    }
    scene.add(refusalGroup);

    // Red Coin (Buyer -> Merchant payment)
    const coinGroup = new THREE.Group();
    coinGroup.visible = false;
    {
      const coinMat = new THREE.MeshStandardMaterial({
        color: 0xdc2626,
        emissive: 0x991b1b,
        emissiveIntensity: 0.35,
        roughness: 0.25,
        metalness: 0.2
      });
      const disc = new THREE.Mesh(new THREE.CylinderGeometry(0.38, 0.38, 0.12, 32), coinMat);
      disc.rotation.x = Math.PI / 2;
      coinGroup.add(disc);

      const rim = new THREE.Mesh(
        new THREE.TorusGeometry(0.38, 0.045, 16, 36),
        new THREE.MeshStandardMaterial({ color: 0xfef2f2, roughness: 0.3 })
      );
      coinGroup.add(rim);
    }
    scene.add(coinGroup);

    // DOM Overlay Elements
    const stationLabelEls = {
      buyer: document.getElementById('label-buyer'),
      agent: document.getElementById('label-agent'),
      spend: document.getElementById('label-spend'),
      vault: document.getElementById('label-vault'),
      merchant: document.getElementById('label-merchant'),
      chain: document.getElementById('label-chain')
    };

    const badgePacket = document.getElementById('badge-packet');
    const badgeRefusal = document.getElementById('badge-refusal');
    const badgeCoin = document.getElementById('badge-coin');
    const badgeSettled = document.getElementById('badge-settled');
    const captionTextEl = document.getElementById('caption-text');
    const captionStatusEl = document.getElementById('caption-status-pill');

    function setCaption(sentence, orderId, statusText, statusClass, t) {
      const fullPlainText = orderId ? `${sentence} ${orderId}` : sentence;
      internal.addLabel(fullPlainText, t, orderId);

      if (orderId) {
        captionTextEl.innerHTML = `${sentence} <span class="caption-order-id">${orderId}</span>`;
      } else {
        captionTextEl.textContent = sentence;
      }

      captionStatusEl.textContent = statusText || 'Replay';
      captionStatusEl.className = statusClass ? statusClass : '';
    }

    function showBadge(el, textMain, orderId, t) {
      const fullPlain = orderId ? `${textMain} ${orderId}` : textMain;
      internal.addLabel(fullPlain, t, orderId);
      if (orderId) {
        el.innerHTML = `${textMain} <span class="badge-order">${orderId}</span>`;
      } else {
        el.textContent = textMain;
      }
      el.classList.add('visible');
    }

    function hideBadge(el) {
      el.classList.remove('visible');
    }

    function projectToScreen(pos3D, el) {
      const v = pos3D.clone().project(camera);
      let x = (v.x * 0.5 + 0.5) * window.innerWidth;
      let y = (-v.y * 0.5 + 0.5) * window.innerHeight;
      const halfW = (el.offsetWidth || 120) * 0.5;
      const margin = 18;
      x = Math.max(halfW + margin, Math.min(window.innerWidth - halfW - margin, x));
      y = Math.max(64, Math.min(window.innerHeight - 115, y));
      el.style.left = `${x}px`;
      el.style.top = `${y}px`;
    }

    function lerp(a, b, u) {
      const clamped = Math.max(0, Math.min(1, u));
      return a + (b - a) * clamped;
    }

    function smoothstep(u) {
      const c = Math.max(0, Math.min(1, u));
      return c * c * (3 - 2 * c);
    }

    const flags = {
      beat1Started: false,
      beat1Refused: false,
      beat1Cleared: false,
      beat2Started: false,
      beat2Sealed: false,
      beat2CoinStarted: false,
      beat2MerchantLit: false,
      beat2LedgerAdded: false
    };

    function updateTimeline() {
      const t = internal.nowMs();

      // Subtle camera drift keeping all 6 stations well inside 1280x720 frame
      const driftAngle = t * 0.00035;
      camera.position.x = Math.sin(driftAngle) * 0.22;
      camera.position.y = 6.3 + Math.cos(driftAngle * 0.8) * 0.08;
      camera.lookAt(0, 0.45, 0);
      camera.updateMatrixWorld();

      // ---------------- BEAT 1: REFUSED ORDER ----------------
      if (t >= T_BEAT1_START && !flags.beat1Started) {
        flags.beat1Started = true;
        internal.addMark('refused', ORD_REFUSED, 'refusal', t);

        packetGroup.visible = true;
        const sealMesh = packetGroup.getObjectByName('packetBlueSeal');
        if (sealMesh) sealMesh.visible = false;

        showBadge(badgePacket, 'Payment request', ORD_REFUSED, t);
        setCaption(
          'Gemini agent asked for research payment.',
          ORD_REFUSED,
          'Asked',
          'status-packet',
          t
        );
      }

      if (t >= T_BEAT1_START && t < T_BEAT1_REFUSED) {
        let px;
        if (t < T_BEAT1_SPEND) {
          const u = smoothstep((t - T_BEAT1_START) / (T_BEAT1_SPEND - T_BEAT1_START));
          px = lerp(X_POS.agent, X_POS.spend, u);
          spendGateArm.rotation.z = lerp(0, 0.45, u);
        } else {
          const u = smoothstep((t - T_BEAT1_SPEND) / (T_BEAT1_REFUSED - T_BEAT1_SPEND));
          px = lerp(X_POS.spend, X_POS.vault, u);
          spendGateArm.rotation.z = lerp(0.45, 0, u);
        }
        const arcY = 1.65 + Math.sin(((t - T_BEAT1_START) / (T_BEAT1_REFUSED - T_BEAT1_START)) * Math.PI) * 0.35;
        packetGroup.position.set(px, arcY, 0.35);
        packetGroup.rotation.y = Math.sin(t * 0.006) * 0.2;
        projectToScreen(new THREE.Vector3(px, arcY + 0.5, 0.35), badgePacket);
      }

      if (t >= T_BEAT1_REFUSED && !flags.beat1Refused) {
        flags.beat1Refused = true;
        packetGroup.position.set(X_POS.vault - 0.55, 1.35, 0.45);
        hideBadge(badgePacket);

        internal.addElement(`refusal:${ORD_REFUSED}`, t, ORD_REFUSED);
        refusalGroup.visible = true;

        showBadge(badgeRefusal, `refused ${CODE_REFUSED}`, ORD_REFUSED, t);
        setCaption(
          `Vault refused the payment: ${CODE_REFUSED}`,
          ORD_REFUSED,
          'Refused',
          'status-refused',
          t
        );
      }

      if (flags.beat1Refused && !flags.beat1Cleared) {
        const pulse = 1 + Math.sin((t - T_BEAT1_REFUSED) * 0.008) * 0.06;
        refusalGroup.scale.set(pulse, pulse, pulse);
        projectToScreen(new THREE.Vector3(X_POS.vault, 2.95, 0.45), badgeRefusal);
      }

      if (t >= T_BEAT1_CLEAR && !flags.beat1Cleared) {
        flags.beat1Cleared = true;
        packetGroup.visible = false;
        refusalGroup.visible = false;
        hideBadge(badgeRefusal);
        internal.removeElement(`refusal:${ORD_REFUSED}`, t);
      }

      // ---------------- BEAT 2: SETTLED ORDER ----------------
      if (t >= T_BEAT2_START && !flags.beat2Started) {
        flags.beat2Started = true;
        internal.addMark('settled', ORD_SETTLED, 'coin', t);

        packetGroup.visible = true;
        const sealMesh = packetGroup.getObjectByName('packetBlueSeal');
        if (sealMesh) sealMesh.visible = false;

        showBadge(badgePacket, `Request ${AMT_SETTLED}`, ORD_SETTLED, t);
        setCaption(
          `Gemini agent asked for ${AMT_SETTLED} payment.`,
          ORD_SETTLED,
          'Asked',
          'status-packet',
          t
        );
      }

      if (t >= T_BEAT2_START && t < T_BEAT2_COIN) {
        if (t < T_BEAT2_VAULT) {
          let px;
          if (t < T_BEAT2_SPEND) {
            const u = smoothstep((t - T_BEAT2_START) / (T_BEAT2_SPEND - T_BEAT2_START));
            px = lerp(X_POS.agent, X_POS.spend, u);
            spendGateArm.rotation.z = lerp(0, 0.95, u);
          } else {
            const u = smoothstep((t - T_BEAT2_SPEND) / (T_BEAT2_VAULT - T_BEAT2_SPEND));
            px = lerp(X_POS.spend, X_POS.vault, u);
            spendGateArm.rotation.z = lerp(0.95, 0, u);
          }
          const arcY = 1.65 + Math.sin(((t - T_BEAT2_START) / (T_BEAT2_VAULT - T_BEAT2_START)) * Math.PI) * 0.35;
          packetGroup.position.set(px, arcY, 0.35);
          projectToScreen(new THREE.Vector3(px, arcY + 0.5, 0.35), badgePacket);
        } else {
          // At vault: sealed in blue before coin starts
          if (!flags.beat2Sealed) {
            flags.beat2Sealed = true;
            const sealMesh = packetGroup.getObjectByName('packetBlueSeal');
            if (sealMesh) sealMesh.visible = true;
            vaultSealRing.visible = true;
            vaultKeyMat.emissiveIntensity = 0.95;
          }
          packetGroup.position.set(X_POS.vault, 1.65, 0.55);
          projectToScreen(new THREE.Vector3(X_POS.vault, 2.2, 0.55), badgePacket);
        }
      }

      // Coin moves Buyer -> Merchant only AFTER vault seals packet
      if (t >= T_BEAT2_COIN && !flags.beat2CoinStarted) {
        flags.beat2CoinStarted = true;
        packetGroup.visible = false;
        hideBadge(badgePacket);

        internal.addElement(`coin:${ORD_SETTLED}`, t, ORD_SETTLED);
        coinGroup.visible = true;
        showBadge(badgeCoin, AMT_SETTLED, ORD_SETTLED, t);
      }

      if (t >= T_BEAT2_COIN) {
        if (t < T_BEAT2_MERCHANT) {
          const u = smoothstep((t - T_BEAT2_COIN) / (T_BEAT2_MERCHANT - T_BEAT2_COIN));
          const cx = lerp(X_POS.buyer, X_POS.merchant, u);
          const cy = 1.55 + Math.sin(u * Math.PI) * 1.15;
          coinGroup.position.set(cx, cy, 0.65);
          coinGroup.rotation.y = (t - T_BEAT2_COIN) * 0.006;
          projectToScreen(new THREE.Vector3(cx, cy + 0.55, 0.65), badgeCoin);
        } else {
          // Coin lands at Merchant (Chain is never the recipient of the coin)
          coinGroup.position.set(X_POS.merchant, 1.35, 0.72);
          coinGroup.rotation.y = Math.sin(t * 0.003) * 0.25;
          projectToScreen(new THREE.Vector3(X_POS.merchant, 2.95, 0.4), badgeCoin);

          if (!flags.beat2MerchantLit) {
            flags.beat2MerchantLit = true;
            setMerchantLit(true);
          }
        }
      }

      // Separate ledger cue on Base Sepolia Chain: appended red block + pulse
      if (t >= T_BEAT2_LEDGER && !flags.beat2LedgerAdded) {
        flags.beat2LedgerAdded = true;
        appendedLedgerBlockGroup.visible = true;

        showBadge(badgeSettled, `${AMT_SETTLED} · ${HASH_SETTLED}`, ORD_SETTLED, t);
        setCaption(
          `Settled on Base Sepolia: ${AMT_SETTLED}, receipt ${HASH_SETTLED}`,
          ORD_SETTLED,
          'Settled',
          'status-settled',
          t
        );
      }

      if (flags.beat2LedgerAdded) {
        const dtLedger = t - T_BEAT2_LEDGER;
        const pulsePhase = (dtLedger % 1600) / 1600;
        const ringScale = 1 + pulsePhase * 1.6;
        ledgerPulseRing.scale.set(ringScale, ringScale, 1);
        ledgerPulseRing.material.opacity = Math.max(0, 0.85 * (1 - pulsePhase));
        projectToScreen(new THREE.Vector3(X_POS.chain, 1.55, 0.25), badgeSettled);
      }

      // Project static station labels
      projectToScreen(new THREE.Vector3(X_POS.buyer, -0.72, 0.6), stationLabelEls.buyer);
      projectToScreen(new THREE.Vector3(X_POS.agent, -0.72, 0.6), stationLabelEls.agent);
      projectToScreen(new THREE.Vector3(X_POS.spend, -0.72, 0.6), stationLabelEls.spend);
      projectToScreen(new THREE.Vector3(X_POS.vault, -0.72, 0.6), stationLabelEls.vault);
      projectToScreen(new THREE.Vector3(X_POS.merchant, -0.72, 0.6), stationLabelEls.merchant);
      projectToScreen(new THREE.Vector3(X_POS.chain, -0.72, 0.6), stationLabelEls.chain);

      if (t >= T_DONE && !window.__theater.done) {
        window.__theater.done = true;
      }
    }

    function animate() {
      updateTimeline();
      renderer.render(scene, camera);
      requestAnimationFrame(animate);
    }

    // Immediate synchronous render at t=0 so all 6 stations and labels are visible on Frame 0
    updateTimeline();
    renderer.render(scene, camera);

    // Background timer backup so marks/done advance reliably even if rAF is throttled
    setInterval(updateTimeline, 100);

    window.addEventListener('resize', () => {
      camera.aspect = window.innerWidth / window.innerHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(window.innerWidth, window.innerHeight);
      updateTimeline();
      renderer.render(scene, camera);
    });

    requestAnimationFrame(animate);
  </script>
